import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"09 - REST API Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/broker-integration-checklist.md","filePath":"developers/design-documentation/broker-integration-checklist.md"}'),r={name:"developers/design-documentation/broker-integration-checklist.md"};function s(n,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="_09-rest-api-architecture" tabindex="-1">09 - REST API Architecture <a class="header-anchor" href="#_09-rest-api-architecture" aria-label="Permalink to &quot;09 - REST API Architecture&quot;">​</a></h1><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p><code>restx_api/__init__.py</code> creates <code>api_v1_bp</code> with prefix <code>/api/v1</code> and registers 47 namespaces, which expose 63 current method/path pairs across order, account, market-data, option, calendar, analyzer, portfolio, SIP, preference, messaging, and utility namespaces.</p><p>The Flask-RESTX <code>Api</code> is configured with <code>doc=False</code>. Swagger/OpenAPI UI is intentionally disabled and there is no supported <code>/api/docs</code> route. The maintained external contract is the <a href="./../../api-documentation/v1/README">API documentation</a>.</p><h2 id="resource-pattern" tabindex="-1">Resource Pattern <a class="header-anchor" href="#resource-pattern" aria-label="Permalink to &quot;Resource Pattern&quot;">​</a></h2><p>Most resources follow this sequence:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request JSON/query</span></span>
<span class="line"><span>  -&gt; Marshmallow schema</span></span>
<span class="line"><span>  -&gt; service call</span></span>
<span class="line"><span>  -&gt; jsonify normalized wrapper</span></span></code></pre></div><p>Schemas are split by domain:</p><table tabindex="0"><thead><tr><th>File</th><th>Scope</th></tr></thead><tbody><tr><td><code>restx_api/schemas.py</code></td><td>Orders, options execution, margin, GTT</td></tr><tr><td><code>restx_api/data_schemas.py</code></td><td>Quotes, history, symbols, calendar, Greeks, instruments</td></tr><tr><td><code>restx_api/account_schema.py</code></td><td>Account, analyzer, ping, chart, P&amp;L</td></tr></tbody></table><p>Unknown fields are excluded by most schemas. <code>ChartSchema</code> explicitly includes unknown fields because chart preferences are extensible.</p><h2 id="authentication-and-csrf" tabindex="-1">Authentication And CSRF <a class="header-anchor" href="#authentication-and-csrf" aria-label="Permalink to &quot;Authentication And CSRF&quot;">​</a></h2><p>REST resources generally accept <code>apikey</code> in JSON for POST or query parameters for GET. Telegram and WhatsApp resources also support <code>X-API-KEY</code> on selected calls. The Telegram webhook uses its Telegram secret header.</p><p><code>app.py</code> exempts the <code>/api/v1</code> blueprint from CSRF because these calls do not use the browser form/session trust boundary. API-key verification remains mandatory unless an endpoint has a separate external authentication contract.</p><h2 id="rate-limit-classes" tabindex="-1">Rate-Limit Classes <a class="header-anchor" href="#rate-limit-classes" aria-label="Permalink to &quot;Rate-Limit Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Default</th><th>Examples</th></tr></thead><tbody><tr><td><code>API_RATE_LIMIT</code></td><td>50/second from <code>.sample.env</code></td><td>Market data, account reads, chart, analyzer</td></tr><tr><td><code>ORDER_RATE_LIMIT</code></td><td>10/second</td><td>Place/modify/cancel and options/GTT writes</td></tr><tr><td><code>SMART_ORDER_RATE_LIMIT</code></td><td>10/second</td><td>Position-aware smart order</td></tr><tr><td>Endpoint-specific</td><td>Varies</td><td>Greeks (30/minute), SIP and portfolio backtests (10/minute), tearsheet (5/minute), Telegram and WhatsApp (30/minute)</td></tr></tbody></table><p>All are environment/configuration values; compound limits joined by semicolons are supported. Note that most <code>restx_api</code> modules fall back to <code>10 per second</code> for <code>API_RATE_LIMIT</code> when the key is absent from <code>.env</code>, not to the <code>50 per second</code> shown in <code>.sample.env</code>. See <a href="./36-rate-limiting-guide">36 Rate Limiting</a>.</p><h2 id="mode-routing" tabindex="-1">Mode Routing <a class="header-anchor" href="#mode-routing" aria-label="Permalink to &quot;Mode Routing&quot;">​</a></h2><ul><li>Live mode resolves <code>broker.&lt;key&gt;</code> modules through the active API-key session.</li><li>Analyzer mode routes supported order/account operations to the sandbox engine.</li><li>Analyzer GTT place, modify, cancel and orderbook route to <code>sandbox/gtt_manager.py</code>. In live mode the same four services return 501 when the selected broker ships no <code>api/gtt_api.py</code>, which today means every broker except Dhan and Zerodha.</li><li>Semi-auto mode queues eligible execution in Action Center and blocks defined destructive operations.</li><li><code>/pnl/symbols</code> is analyzer-only.</li></ul><h2 id="validation-details" tabindex="-1">Validation Details <a class="header-anchor" href="#validation-details" aria-label="Permalink to &quot;Validation Details&quot;">​</a></h2><ul><li>Regular order quantity is numeric and positive. Fractional quantity is allowed only for <code>CRYPTO</code>; other exchanges are coerced to whole integers or rejected.</li><li>Options execution quantity is a positive integer.</li><li>Options multi-order accepts 1 to 20 legs.</li><li>Multi-option Greeks accepts 1 to 50 symbols.</li><li>Option-chain <code>strike_count</code>, when provided, is 1 to 100.</li><li>History accepts <code>source=api</code> or <code>source=db</code>; <code>db</code> reads Historify.</li><li>Instruments is GET and can return JSON or CSV.</li></ul><h2 id="response-boundaries" tabindex="-1">Response Boundaries <a class="header-anchor" href="#response-boundaries" aria-label="Permalink to &quot;Response Boundaries&quot;">​</a></h2><p>Tradeboard normalizes wrapper status and core fields, but broker-specific payload data is not exhaustively identical for all 36 plugins. Some endpoints intentionally return CSV, plain text, or empty webhook acknowledgements. Clients must use the endpoint contract rather than assuming every response is <code>{status,data}</code>.</p><h2 id="adding-a-resource" tabindex="-1">Adding A Resource <a class="header-anchor" href="#adding-a-resource" aria-label="Permalink to &quot;Adding A Resource&quot;">​</a></h2><ol><li>Add or reuse a Marshmallow schema.</li><li>Put reusable behavior in <code>services/</code>, not the resource method.</li><li>Register the namespace in <code>restx_api/__init__.py</code>.</li><li>Add the method/path to <code>docs/api/README.md</code> and its endpoint page.</li><li>Add the row to <code>docs/bdd/rest_api_inventory.feature</code> and behavior scenarios where needed.</li><li>Add focused tests for validation, auth, mode routing, and response shape.</li></ol>`,24)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
